function recurrenceFor(input:{cadence:"daily"|"weekly"|"monthly"|"yearly"|"interval";interval_days?:number|undefined;next_due_on:string;anchor_on?:string|undefined;missing_date_policy:"skip"|"last_day";recurrence_rule?:string|undefined}):{anchorOn:string;rule:string}{
  const anchorOn=input.anchor_on??input.next_due_on;
  const rule=input.recurrence_rule??buildRecurrenceRule({cadence:input.cadence,intervalDays:input.interval_days,anchorOn,missingDatePolicy:input.missing_date_policy});
  const parsed=parseRecurrenceRule(rule),expected=input.cadence==="interval"?"DAILY":input.cadence.toUpperCase();
  if(parsed.frequency!==expected)throw conflict("recurrence_rule frequency does not match cadence");
  if(input.cadence==="interval"&&parsed.interval!==input.interval_days)throw conflict("recurrence_rule interval does not match interval_days");
  return{anchorOn,rule};
}

function camelizeRecord(value:Record<string,unknown>):Record<string,unknown>{return Object.fromEntries(Object.entries(value).map(([key,item])=>[key.replace(/_([a-z])/gu,(_,letter:string)=>letter.toUpperCase()),item]));}

function projectLifeRecord(value:Record<string,unknown>,sections:readonly ("meal"|"purchase"|"money"|"sources")[],kind:"record"|"meal"):Record<string,unknown>{
  const visible=new Set(sections),result={...value};
  if(kind==="record"){
    if(!visible.has("meal"))delete result.meals;
    if(!visible.has("purchase")){delete result.purchase;delete result.purchase_items;}
    if(!visible.has("money"))delete result.money_entry;
    if(!visible.has("sources"))delete result.sources;
  }else{
    if(!visible.has("meal")){for(const key of ["occurred_on","occurred_at","time_zone","meal_type","note","revision","items"])delete result[key];}
    if(!visible.has("money"))delete result.payments;
    if(!visible.has("sources"))delete result.sources;
  }
  if(!visible.has("sources"))for(const key of ["purchase","money_entry"]){const nested=result[key];if(nested&&typeof nested==="object"&&!Array.isArray(nested)){const sanitized={...(nested as Record<string,unknown>)};delete sanitized.source_id;result[key]=sanitized;}}
  return result;
}

function trimNumeric(value: string | null): string | null {
  if (value === null) return null;
  return value.includes(".") ? value.replace(/0+$/u, "").replace(/\.$/u, "") : value;
}

function moneyNumeric(value: string): string {
  const [whole, fraction = ""] = value.split(".");
  return `${whole}.${fraction.padEnd(2, "0").slice(0, 2)}`;
}

function stableCursorId(subjectId:string,deviceId:string,sourceId:string,recordType:string):string{return `cursor_${sha256Fingerprinter.fingerprint([subjectId,deviceId,sourceId,recordType]).slice(0,24)}`;}

function mapOperation(row: typeof schema.operations.$inferSelect): StoredOperation {
  return { executionId: row.executionId, subjectId: row.subjectId, commandId: row.commandId, capability: row.capability, ...(row.legacyCapabilityVersion===null?{}:{legacyCapabilityVersion:row.legacyCapabilityVersion}), fingerprint: row.fingerprint, result: executionResultSchema.parse(row.result) };
}

export class PostgresUnitOfWork implements UnitOfWork {
  readonly pool: Pool;
  readonly database: Database;
  constructor(config: PoolConfig | Pool) {
    this.pool = config instanceof Pool ? config : new Pool(config);
    this.database = drizzle(this.pool, { schema });
  }
  transaction<T>(work: (store: TransactionStore) => Promise<T>): Promise<T> {
    return this.database.transaction((transaction) => work(storeFor(transaction)));
  }
  read<T>(work: (store: TransactionStore) => Promise<T>): Promise<T> { return work(storeFor(this.database)); }
  async ensurePrincipal(subjectId: string): Promise<void> { await this.database.insert(schema.principals).values({ id: subjectId }).onConflictDoNothing(); }
  async close(): Promise<void> { await this.pool.end(); }
}
